{
  "root_cause": "The previouslyFocused variable can be null when getActiveEl() returns null (no focused element). The Safari fallback only updates previouslyFocused when its tagName is 'BODY', leaving it null, so hide() cannot restore focus to the opener.",
  "repair_strategy": "Modify the condition in the show() method to treat a null previouslyFocused as needing the fallback to event.target, ensuring a valid reference to the opener is stored before the dialog is opened.",
  "edits": [
    {
      "path": "src/a11y-dialog.js",
      "sha256":"9dbd1daa87fcac8518db48e4cbb4b0eeea7c30c92a6171ff59cbc895938aaf4c",
      "before":"    this.shown = true
    this.$el.removeAttribute('aria-hidden')
    this.previouslyFocused = getActiveEl()               

    // Due to a long lasting bug in Safari, clicking an interactive element
    // (like a <button>) does *not* move the focus to that element, which means
    // `document.activeElement` is whatever element is currently focused (like
    // an <input>), or the <body> element otherwise. We can work around that
    // problem by checking whether the focused element is the <body>, and if it,
    // store the click event target.
    // See: https://bugs.webkit.org/show_bug.cgi?id=22261
    if (this.previouslyFocused?.tagName === 'BODY' && event?.target) {
      this.previouslyFocused = event.target               
    }

    // Set the focus to the dialog element
",
      "after":"    this.shown = true
    this.$el.removeAttribute('aria-hidden')
    this.previouslyFocused = getActiveEl()               

    // Due to a long lasting bug in Safari, clicking an interactive element
    // (like a <button>) does *not* move the focus to that element, which means
    // `document.activeElement` is whatever element is currently focused (like
    // an <input>), or the <body> element otherwise. We can work around that
    // problem by checking whether the focused element is the <body>, and if it,
    // store the click event target.
    // See: https://bugs.webkit.org/show_bug.cgi?id=22261
    if ((!this.previouslyFocused || this.previouslyFocused?.tagName === 'BODY') && event?.target) {
      this.previouslyFocused = event.target               
    }

    // Set the focus to the dialog element
"
    }
  ],
  "expected_accessibility_effect": "Focus returns to the opener after closing the dialog with Escape, meeting WCAG 2.1.1 Keyboard, 2.4.3 Focus Order, and 4.1.2 Name, Role, Value.",
  "functional_risks": [],
  "verification_requirements": [
    "Verify that pressing Escape after opening the dialog via Enter returns focus to the opener button.",
    "Verify that clicking the opener and pressing Escape also returns focus to the opener.",
    "Ensure the existing Safari workaround for body-focused clicks continues to function correctly."
  ]
}
